//! Integration tests for runtime metadata generated by the model derive.

use std::collections::HashMap;

use model_runtime::AttributeKind;
use model_runtime::AttributeMetadata;
use model_runtime::AttributeQuery;
use model_runtime::DecimalSemantic;
use model_runtime::HasTypeShape;
use model_runtime::RoundingMode;
use model_runtime::SensitiveHandling;
use model_runtime::TemporalNormalization;
use model_runtime::TemporalPrecision;
use model_runtime::TextFormat;
use model_runtime::TextRepertoire;
use model_runtime::TypeCapabilities;
use model_runtime::TypeKind;
use model_runtime::TypeShape;
use model_runtime::UniqueComparison;
use model_runtime::metadata_of;
use qubit_model_derive::ModelMetadata;

#[allow(dead_code)]
#[derive(ModelMetadata)]
struct User {
    #[model(identifier(generated))]
    id: Option<i64>,
    #[model(unique(ignore_case), index)]
    nickname: Option<String>,
}

#[derive(ModelMetadata)]
struct Empty;

#[derive(ModelMetadata)]
#[allow(dead_code)]
struct UserId(i64);

#[derive(ModelMetadata)]
#[allow(dead_code)]
struct DisplayName(String);

#[derive(ModelMetadata)]
#[model(textual)]
#[allow(dead_code)]
struct Phone {
    country_area: Option<String>,
    city_area: Option<String>,
    number: String,
}

#[derive(ModelMetadata)]
#[allow(dead_code)]
struct PhoneLoginParams {
    #[model(text(format = mobile))]
    mobile: Option<Phone>,
}

#[derive(ModelMetadata)]
#[allow(dead_code)]
enum Status {
    Draft,
    Published,
}

#[allow(dead_code)]
#[derive(ModelMetadata)]
struct Organization {
    id: i64,
}

struct ExternalValue;

#[allow(dead_code)]
#[derive(ModelMetadata)]
#[model(
    primary_key(fields(id), generated(id)),
    unique(
        name = "organization_username",
        fields(organization_id, username),
        ignore_case(username)
    ),
    index(name = "created_at_index", fields(created_at)),
    key(name = "account", fields(organization_id, username)),
    ownership(owner = Organization)
)]
struct AttributedModel {
    id: i64,
    #[model(reference(
        target = Organization,
        target_field = id,
        must_exist = true,
        same_as = "organization.id"
    ))]
    organization_id: i64,
    organization: Organization,
    #[model(lookup_relation(target = Organization, target_field = id))]
    organization_lookup: i64,
    #[model(text(
        min_chars = 3,
        max_chars = 32,
        min_bytes = 3,
        max_bytes = 64,
        repertoire = ascii,
        non_blank,
        format = email
    ))]
    username: String,
    #[model(sequence(min_items = 1, max_items = 5, unique_items))]
    aliases: Vec<String>,
    #[model(element(text(repertoire = ascii)))]
    ascii_codes: [String; 2],
    #[model(map(min_entries = 1, max_entries = 4))]
    labels: HashMap<String, String>,
    #[model(time(precision = millisecond, normalization = utc))]
    created_at: chrono::DateTime<chrono::Utc>,
    #[model(decimal(precision = 8, scale = 3, rounding = half_up))]
    ratio: bigdecimal::BigDecimal,
    #[model(money(precision = 12, scale = 2, rounding = half_even))]
    balance: bigdecimal::BigDecimal,
    #[model(element(decimal(scale = 2)))]
    decimal_values: Vec<bigdecimal::BigDecimal>,
    #[model(text(format = mobile))]
    mobile: String,
    #[model(
        sensitive(mask),
        codec = "encrypted",
        generator(name = "account_balance")
    )]
    secret: String,
    #[model(sensitive(token))]
    verification_code: String,
    #[model(opaque)]
    external: ExternalValue,
}

#[test]
fn test_derive_emits_declared_fields_and_nullable_shape() {
    let metadata = metadata_of::<User>();

    assert_eq!(metadata.fields().count(), 2);
    assert!(
        metadata
            .field("nickname")
            .expect("nickname metadata")
            .is_nullable()
    );
}

#[test]
fn test_shorthand_normalizes_to_type_constraints() {
    let metadata = metadata_of::<User>();

    let primary_key = metadata.primary_key().expect("primary key");
    assert_eq!(
        primary_key
            .fields()
            .iter()
            .map(|field| field.name())
            .collect::<Vec<_>>(),
        ["id"]
    );
    assert!(primary_key.fields()[0].is_generated());

    let unique = metadata
        .unique_constraints()
        .next()
        .expect("unique metadata");
    assert_eq!(
        unique
            .fields()
            .iter()
            .map(|field| (field.name(), field.comparison()))
            .collect::<Vec<_>>(),
        [("nickname", UniqueComparison::IgnoreCase)]
    );

    let index = metadata.indexes().next().expect("index metadata");
    assert_eq!(index.fields(), &["nickname"]);
}

#[test]
fn test_derive_emits_empty_struct_metadata() {
    let metadata = metadata_of::<Empty>();

    assert!(matches!(metadata.kind(), TypeKind::Struct(_)));
    assert_eq!(metadata.fields().count(), 0);
}

#[test]
fn test_derive_emits_newtype_metadata() {
    let metadata = metadata_of::<UserId>();

    assert!(matches!(metadata.kind(), TypeKind::Newtype(newtype)
        if newtype.field().ordinal() == 0
            && newtype.field().name() == "0"
            && newtype.field().rust_type_name() == "i64"));
}

#[test]
fn test_derive_newtype_inherits_inner_type_capabilities() {
    assert_eq!(
        <DisplayName as HasTypeShape>::CAPABILITIES,
        TypeCapabilities::TEXT
    );
}

#[test]
fn test_textual_named_model_accepts_mobile_constraints() {
    assert_eq!(
        <Phone as HasTypeShape>::CAPABILITIES,
        TypeCapabilities::TEXT
    );
    assert!(matches!(
        metadata_of::<PhoneLoginParams>()
            .field("mobile")
            .expect("mobile field metadata")
            .text_constraint(),
        Some(constraint) if constraint.format() == Some(TextFormat::Mobile)
    ));
}

#[test]
fn test_derive_emits_fieldless_enum_metadata() {
    let metadata = metadata_of::<Status>();

    assert!(matches!(metadata.kind(), TypeKind::Enum(enum_metadata)
        if enum_metadata.variants().len() == 2
            && enum_metadata.variants()[0].name() == "Draft"
            && enum_metadata.variants()[1].ordinal() == 1));
}

#[test]
fn test_model_attributes_expand_in_canonical_form() {
    let metadata = metadata_of::<AttributedModel>();

    let primary_key = metadata.primary_key().expect("primary key metadata");
    assert_eq!(
        primary_key
            .fields()
            .iter()
            .map(|field| (field.name(), field.is_generated()))
            .collect::<Vec<_>>(),
        [("id", true)]
    );
    let unique = metadata
        .unique_constraints()
        .next()
        .expect("unique metadata");
    assert_eq!(unique.name(), Some("organization_username"));
    assert_eq!(
        unique.comparison_of("organization_id"),
        Some(UniqueComparison::Exact)
    );
    assert_eq!(
        unique.comparison_of("username"),
        Some(UniqueComparison::IgnoreCase)
    );
    let index = metadata.indexes().next().expect("index metadata");
    assert_eq!(index.name(), Some("created_at_index"));
    assert_eq!(index.fields(), &["created_at"]);
    assert!(matches!(
        metadata.attribute(AttributeKind::Key),
        Some(AttributeMetadata::Key(key))
            if key.name() == Some("account") && key.contains("username")
    ));
    assert!(matches!(
        metadata.attribute(AttributeKind::Ownership),
        Some(AttributeMetadata::Ownership(ownership))
            if ownership.owner().identity().type_name()
                == core::any::type_name::<Organization>()
    ));
}

#[test]
fn test_text_sequence_and_map_attributes_expand() {
    let metadata = metadata_of::<AttributedModel>();
    let text = metadata
        .field("username")
        .expect("username metadata")
        .text_constraint()
        .expect("text constraint");
    assert_eq!(text.min_chars(), Some(3));
    assert_eq!(text.max_chars(), Some(32));
    assert_eq!(text.min_bytes(), Some(3));
    assert_eq!(text.max_bytes(), Some(64));
    assert_eq!(text.repertoire(), TextRepertoire::Ascii);
    assert!(text.is_non_blank());
    assert_eq!(text.format(), Some(TextFormat::Email));

    assert!(matches!(
        metadata
            .field("aliases")
            .expect("aliases metadata")
            .attribute(AttributeKind::Sequence),
        Some(AttributeMetadata::Sequence(sequence))
            if sequence.min_items() == Some(1)
                && sequence.max_items() == Some(5)
                && sequence.has_unique_items()
    ));
    assert!(matches!(
        metadata
            .field("labels")
            .expect("labels metadata")
            .attribute(AttributeKind::Map),
        Some(AttributeMetadata::Map(map))
            if map.min_entries() == Some(1) && map.max_entries() == Some(4)
    ));
}

#[test]
fn test_temporal_decimal_and_money_attributes_expand() {
    let metadata = metadata_of::<AttributedModel>();

    assert!(matches!(
        metadata
            .field("created_at")
            .expect("created_at metadata")
            .attribute(AttributeKind::Temporal),
        Some(AttributeMetadata::Temporal(temporal))
            if temporal.precision() == TemporalPrecision::Millisecond
                && temporal.normalization() == TemporalNormalization::Utc
    ));
    assert!(matches!(
        metadata
            .field("ratio")
            .expect("ratio metadata")
            .attribute(AttributeKind::Decimal),
        Some(AttributeMetadata::Decimal(decimal))
            if decimal.precision() == Some(8)
                && decimal.scale() == 3
                && decimal.rounding() == RoundingMode::HalfUp
                && decimal.semantic() == DecimalSemantic::Number
    ));
    assert!(matches!(
        metadata
            .field("balance")
            .expect("balance metadata")
            .attribute(AttributeKind::Decimal),
        Some(AttributeMetadata::Decimal(decimal))
            if decimal.precision() == Some(12)
                && decimal.scale() == 2
                && decimal.rounding() == RoundingMode::HalfEven
                && decimal.semantic() == DecimalSemantic::Money
    ));
}

#[test]
fn test_migrated_element_and_mobile_constraints_expand() {
    let metadata = metadata_of::<AttributedModel>();
    let ascii_element = metadata
        .field("ascii_codes")
        .expect("ascii_codes metadata")
        .element_metadata()
        .expect("ASCII element metadata");
    assert!(matches!(
        ascii_element.attributes(),
        [AttributeMetadata::Text(text)]
            if text.repertoire() == TextRepertoire::Ascii
    ));

    let decimal_element = metadata
        .field("decimal_values")
        .expect("decimal_values metadata")
        .element_metadata()
        .expect("decimal element metadata");
    assert!(matches!(
        decimal_element.attributes(),
        [AttributeMetadata::Decimal(decimal)]
            if decimal.scale() == 2
                && decimal.semantic() == DecimalSemantic::Number
    ));

    assert_eq!(
        metadata
            .field("mobile")
            .expect("mobile metadata")
            .text_constraint()
            .and_then(|text| text.format()),
        Some(TextFormat::Mobile)
    );
}

#[test]
fn test_reference_sensitive_and_strategy_attributes_expand() {
    let metadata = metadata_of::<AttributedModel>();
    let reference = metadata
        .field("organization_id")
        .expect("organization_id metadata")
        .reference()
        .expect("reference metadata");
    assert_eq!(
        reference.target().identity().type_name(),
        core::any::type_name::<Organization>()
    );
    assert_eq!(reference.target_field().segments(), &["id"]);
    assert!(reference.must_exist());
    assert_eq!(
        reference.same_as().expect("same-as path").segments(),
        &["organization", "id"]
    );

    let lookup = metadata
        .field("organization_lookup")
        .expect("organization lookup metadata")
        .lookup_relation()
        .expect("lookup relation metadata");
    assert_eq!(
        lookup.target().identity().type_name(),
        core::any::type_name::<Organization>()
    );
    assert_eq!(lookup.target_field().segments(), &["id"]);

    let secret = metadata.field("secret").expect("secret metadata");
    assert!(matches!(
        secret.attribute(AttributeKind::Sensitive),
        Some(AttributeMetadata::Sensitive(sensitive))
            if sensitive.handling() == SensitiveHandling::Mask
    ));
    assert!(matches!(
        metadata
            .field("verification_code")
            .expect("verification_code metadata")
            .attribute(AttributeKind::Sensitive),
        Some(AttributeMetadata::Sensitive(sensitive))
            if sensitive.handling() == SensitiveHandling::Token
    ));
    assert!(matches!(
        secret.attribute(AttributeKind::Codec),
        Some(AttributeMetadata::Codec(codec)) if codec.name() == "encrypted"
    ));
    assert!(matches!(
        secret.attribute(AttributeKind::Generator),
        Some(AttributeMetadata::Generator(generator))
            if generator.name() == "account_balance"
    ));
}

#[test]
fn test_opaque_field_does_not_require_has_type_shape() {
    let field = metadata_of::<AttributedModel>()
        .field("external")
        .expect("external metadata");

    assert!(matches!(field.field_type().shape(), TypeShape::Opaque));
    assert_eq!(
        field.field_type().type_name(),
        core::any::type_name::<ExternalValue>()
    );
}
